package com.hospital.smartqueue.doctor.scheduling.application;
import com.hospital.smartqueue.common.domain.*; import com.hospital.smartqueue.common.infrastructure.AuditService; import com.hospital.smartqueue.doctor.scheduling.api.*; import com.hospital.smartqueue.doctor.scheduling.domain.ScheduleException; import com.hospital.smartqueue.doctor.scheduling.infrastructure.ScheduleExceptionRepository; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ScheduleExceptionService { private final SchedulingAccessContext access; private final ScheduleExceptionRepository repo; private final AuditService audit; public ScheduleExceptionService(SchedulingAccessContext a,ScheduleExceptionRepository r,AuditService au){access=a;repo=r;audit=au;} @Transactional public ScheduleException create(UUID h,UUID b,UUID d,ScheduleExceptionRequest r){access.requireManage(h,b,d);if(repo.existsByDoctorIdAndBranchIdAndExceptionDate(d,b,r.date()))throw new ConflictException("Schedule exception already exists");ScheduleException e=repo.save(new ScheduleException(d,b,r.date()));audit.record("SCHEDULE_EXCEPTION_CREATED","SCHEDULE_EXCEPTION",e.getId(),h,"{}");return e;} @Transactional(readOnly=true) public ScheduleException get(UUID h,UUID b,UUID d,UUID id){access.requireRead(h,b,d);return owned(d,b,id);} @Transactional public ScheduleException update(UUID h,UUID b,UUID d,UUID id,ScheduleExceptionRequest r){access.requireManage(h,b,d);ScheduleException e=owned(d,b,id);if(r.expectedVersion()==null||r.expectedVersion()!=e.getVersion())throw new ConflictException("STALE_REVISION");if(!e.getExceptionDate().equals(r.date())&&repo.existsByDoctorIdAndBranchIdAndExceptionDate(d,b,r.date()))throw new ConflictException("Schedule exception already exists");e.replace(r.date());audit.record("SCHEDULE_EXCEPTION_UPDATED","SCHEDULE_EXCEPTION",id,h,"{}");return e;} @Transactional public void delete(UUID h,UUID b,UUID d,UUID id,long version){access.requireManage(h,b,d);ScheduleException e=owned(d,b,id);if(e.getVersion()!=version)throw new ConflictException("STALE_REVISION");repo.delete(e);audit.record("SCHEDULE_EXCEPTION_DELETED","SCHEDULE_EXCEPTION",id,h,"{}");} private ScheduleException owned(UUID d,UUID b,UUID id){return repo.findByIdAndDoctorIdAndBranchId(id,d,b).orElseThrow(()->new NotFoundException("Requested resource was not found"));}}
